import memfs from 'memfs'
import { createConsoleLogger, NowConfig, type FileSystem, GUID, type Telemetry } from '@servicenow/sdk-build-core'
import { type DownloadOptions, type IConnector, Orchestrator, Project } from '../../src'
import { MockConnector } from './mock-connector'
import { packMetadata } from './utils'

describe('Orchestrator.transform Test Suite', () => {
    const logger = createConsoleLogger()
    const scopeId = GUID()

    let orchestrator: Orchestrator
    let connector: IConnector
    let project: Project
    let telemetry: Telemetry

    beforeEach(async () => {
        telemetry = {
            sendEvent: jest.fn(),
            error: jest.fn(),
            startTimerEvent: jest.fn().mockReturnValue({
                end: jest.fn().mockReturnValue({ name: 'download', data: {} }),
            }),
        } as unknown as Telemetry

        project = new Project({
            fileSystem: memfs.createFsFromVolume(new memfs.Volume()) as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId }, logger),
            telemetryClient: telemetry,
        })

        const body = await packMetadata(['businessrule.xml', 'sys_ui_form.xml'])
        const response = new Response(body)

        connector = new MockConnector({
            download: jest.fn(async () => response),
            downloadUpdateSet: jest.fn(async () => response),
        })

        orchestrator = new Orchestrator(project, connector)
    })

    it('should download packages', async () => {
        const options: DownloadOptions = {
            method: 'incremental',
        }

        await orchestrator.download(options)
        expect(connector.download).toHaveBeenCalledWith(scopeId, options)
        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('download')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()
    })

    it('should download update sets', async () => {
        const updateSetId = GUID()
        const options: DownloadOptions = {
            method: 'update-set',
            updateSetId,
        }

        await orchestrator.download(options)
        expect(connector.downloadUpdateSet).toHaveBeenCalledWith(updateSetId, scopeId)
        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('download')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()
    })
})
